tools: 2 match(es) for "memory remember layer"
{"description":"All of `memory`, called directly by its own name: adds layer, cues, scope, trigger, supersedes, old, since, until. Long-term memory. search {query}; get {name}; remember {text, layer}; forget {name=layer/n.md, text=reason}.","input_schema":{"additionalProperties":false,"properties":{"cues":{"description":"Comma-separated recall cues.","type":"string"},"layer":{"enum":["profile","episodic","semantic","procedural","prospective"]},"name":{"type":"string"},"old":{"description":"edit: the one span `text` replaces; omit for the whole body.","type":"string"},"op":{"enum":["search","get","remember","edit","forget"]},"query":{"type":"string"},"scope":{"enum":["user","project"]},"since":{"description":"search: notes changed on/after this day or instant.","type":"string"},"supersedes":{"description":"layer/name.md this replaces, same layer.","type":"string"},"text":{"type":"string"},"trigger":{"description":"prospective: at:<rfc3339>, kw:<a,b> or path:<glob>.","type":"string"},"until":{"description":"search: notes changed before this day or instant.","type":"string"}},"required":["op"],"type":"object"},"name":"memory"}
{"description":"Stage a change to the owner's skills (create/edit/patch/delete/write_file); the owner approves it with `overseer memory pending approve`. content = a whole SKILL.md; patch needs old+new matching once; write_file adds one supporting file.","input_schema":{"additionalProperties":false,"properties":{"content":{"description":"create/edit: the whole SKILL.md; write_file: the file's text.","type":"string"},"name":{"description":"The skill's directory name.","type":"string"},"new":{"description":"patch: its replacement.","type":"string"},"old":{"description":"patch: text to replace, exactly once.","type":"string"},"op":{"enum":["create","edit","patch","delete","write_file"],"type":"string"},"path":{"description":"write_file: path inside the skill dir.","type":"string"}},"required":["op","name"],"type":"object"},"name":"skill_edit"}
